#!/usr/bin/env python3
"""Render resources/index.md from data/resources.csv."""

import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main() -> None:
    rows = list(csv.DictReader((ROOT / "data" / "resources.csv").open()))
    lines = [
        "# Resources",
        "",
        "<!-- This file is generated by scripts/build_resource_list.py. Do not edit by hand. -->",
        "",
    ]
    for row in rows:
        lines.append(f"- [{row['name']}]({row['url']}): {row['description']}")
    (ROOT / "resources" / "index.md").write_text("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
